# ==============================================================================# 019_OBSERVABILITY_ENGINE.py# ==============================================================================import sqlite3import jsonimport platformimport socketfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS observability(    id INTEGER PRIMARY KEY AUTOINCREMENT,    timestamp TEXT,    hostname TEXT,    platform TEXT,    python TEXT,    cpu TEXT,    ram TEXT,    disk TEXT,    status TEXT)""")conn.commit()hostname = socket.gethostname()plat = platform.platform()python = platform.python_version()cur.execute("""INSERT INTO observability(    timestamp,    hostname,    platform,    python,    cpu,    ram,    disk,    status)VALUES(?,?,?,?,?,?,?,?)""",(    datetime.now().isoformat(),    hostname,    plat,    python,    "UNKNOWN",    "UNKNOWN",    "UNKNOWN",    "ONLINE"))conn.commit()cur.execute("""SELECT *FROM observabilityORDER BY id DESCLIMIT 1""")print("="*80)print("OBSERVABILITY")print("="*80)print(json.dumps(dict(cur.fetchone()),indent=4,ensure_ascii=False))print("="*80)conn.close()

